// Enum for network titles
export enum NetworkTitle {
    MTN = 'MTN',
    GLO = 'GLO',
    AIRTEL = 'AIRTEL',
    ETISALAT = 'ETISALAT',
}
  

export const extractNetworkTitle = (input: string): NetworkTitle  => {
    const data = input.toUpperCase();
    return (Object.values(NetworkTitle) as string[]).find(title =>
        data.includes(title)
    ) as NetworkTitle;
  }

